// The test component the profile's runtime drives (docs/SCE_TEST_PROFILE.md §12.3)
// ======================================================================

// JobTesterComponent is the test component `job_tester` as the
// profile's runtime drives it (docs/SCE_TEST_PROFILE.md §12.3).
//
// It owns the machine of the policy above, unchanged, and reaches it only
// through the doors the engine already has: the machine's sends on a port leave
// through the test-port processor and its PTCs through the test-component
// invoker, both registered here over the component's runtime context
// (docs/adr/0084), and each round's snapshot is the one external event every
// branch is a transition on. The runtime never reports a PTC's completion to
// the engine: a done branch reads it from the snapshot, so the engine cancels
// every PTC it started when the invoking state is exited, which is P9's kill.
// One goroutine; the engine's scheduler takes no part, since a component sends
// nothing delayed.
//
// The machine is built when the component starts, around a policy the context
// is already set on, and there is none before. The zero value is a component
// that has not started.
type JobTesterComponent struct {
	machine *sce.Engine[JobTesterState, JobTesterEvent]
}

// JobTesterComponent is driven by the profile's runtime.
var _ scetestprofile.ComponentMachine = (*JobTesterComponent)(nil)

// Start builds the machine with context and starts it.
func (c *JobTesterComponent) Start(context *scetestprofile.ComponentContext) {
	policy := NewJobTesterPolicy()
	// The session is named by the component, and named rather than drawn. The
	// name is `mtc` or the id of the `<invoke>` that creates the PTC
	// (ComponentContext.Create, which creates nothing under a name its
	// configuration has no PTC of), and every `<invoke id>` is refused where
	// its document is parsed unless it is an XML Name, which is an Nmtoken
	// (docs/adr/0045). The refusal below is therefore unreachable for a
	// component a generated one creates.
	if err := policy.SetSessionID(context.Name()); err != nil {
		panic("a test component's name is an XML Name, which names a session: " + err.Error())
	}
	policy.sceTestContext = context
	// §11.5, §11.8: the module parameters take the suite's values before the
	// machine is built. Without one, or with one not of its type, the run ends
	// in error (P13), and the machine is not started on a value made up in its
	// place: the component stays one that has not started.
	if !context.ReadModuleParameters(policy.sceAcceptModuleParameters) {
		return
	}
	machine := sce.NewEngine[JobTesterState, JobTesterEvent](&policy)
	// P6: a send on a port is appended to the queue of the port it is connected
	// to, or handed to the system adapter where it is mapped. A test-port send
	// always carries its template's value, with the name of its record type
	// and the writer of its canonical form in the test log (§12.5,
	// `forge::static_lowering`, `StaticTarget::test_message`).
	machine.RegisterEventProcessor("http://sce.dev/ext/test-port", func(request sce.HostSendRequest) []sce.HostSendResponse {
		value, carried := request.Value.(scetestprofile.TestValue)
		if !carried {
			panic("a test-port send carries its template's value")
		}
		context.Send(request.Target, scetestprofile.Message{Event: request.EventName, Value: value})
		return nil
	})
	// P9: the start of a PTC's invocation creates and starts it, and its cancel
	// removes it, whether it is still running or already done.
	machine.RegisterInvoker("http://sce.dev/ext/test-component", func(event sce.HostInvokeEvent) *sce.HostInvokeResponse {
		if event.Start != nil {
			context.Create(event.Start.InvokeID)
		}
		if event.Cancel != nil {
			context.Kill(event.Cancel.InvokeID)
		}
		return nil
	})
	// A test component holds no script engine (`needs_script_engine` is false
	// for every one), so its start has no script session to be refused for.
	if err := machine.Initialize(); err != nil {
		panic("a test component's machine has no script session to fail: " + err.Error())
	}
	c.machine = machine
}

// DeliverSnapshot delivers the round's snapshot (§3.2 step 3), on which the
// machine takes the first branch whose guard holds (P3) and completes its
// macrostep (P4), or takes none and discards the event (§7).
func (c *JobTesterComponent) DeliverSnapshot() {
	if c.machine == nil {
		return
	}
	c.machine.ProcessEvent(JobTesterEventSceTestSnapshot)
}

// Terminated reports whether the machine entered a top-level `<final>` (P10).
func (c *JobTesterComponent) Terminated() bool {
	return c.machine != nil && c.machine.IsInFinalState()
}

// JobTesterInvokeParams holds the values a parent's `<param>` and
// `namelist` give this machine's variables before it starts (§scxml-6.4.1). A
// variable left nil, or absent for an optional one, keeps the value its `<data>`
// gave it.
type JobTesterInvokeParams struct {
	VElapsed *uint32
}

// AcceptParams gives this machine the values handed carries, each as the
// initial value of its variable in place of the one its `<data>` gives, so
// that a variable declared after it whose initial value reads it reads the
// handed value (§scxml-6.4, docs/adr/0098). Called before it initializes.
func (p *JobTesterPolicy) AcceptParams(handed JobTesterInvokeParams) {
	vElapsedLimit := p.vElapsedLimit
	var vElapsed uint32
	if handed.VElapsed != nil {
		vElapsed = *handed.VElapsed
	} else {
		vElapsed = 0
	}
	p.vElapsedLimit = vElapsedLimit
	p.vElapsed = vElapsed
}



// No script engine needed for this state machine, so it has no script session
// to fail and its start is never refused for one.
func (p *JobTesterPolicy) InitializeDataModel(eng *sce.Engine[JobTesterState, JobTesterEvent]) *sce.ScriptSessionFailure {
	return nil
}

// SetParamValueInScriptEngine is a no-op for state machines without script engine.
func (p *JobTesterPolicy) SetParamValueInScriptEngine(name string, value interface{}) {}


// ExecutePendingInvokes starts deferred child state machines (W3C SCXML 6.4).
// Port of Rust do_execute_pending_invokes().
func (p *JobTesterPolicy) ExecutePendingInvokes(engine *sce.Engine[JobTesterState, JobTesterEvent]) {
	if len(p.pendingInvokes) == 0 {
		return
	}

	// W3C SCXML 6.4: Copy-and-clear to prevent iterator invalidation
	invokesToExecute := make([]sce.PendingInvoke[JobTesterState], len(p.pendingInvokes))
	copy(invokesToExecute, p.pendingInvokes)
	p.pendingInvokes = p.pendingInvokes[:0]

	for _, pending := range invokesToExecute {
		if pending.DocumentID == "helper" {
			// W3C SCXML 6.4.1: the host declared this `type`, so START the
			// invocation rather than refusing it. The id handed over is the
			// DOCUMENT's, not the per-instance one the pending queue carries:
			// `done.invoke.<id>` is the name the author wrote a transition
			// for, so it is the name the host must answer on.
			// W3C SCXML 6.4.1: what the request says is evaluated now, when the
			// invocation starts, by the rules the other invoke kinds follow: an
			// attribute that cannot be evaluated starts nothing, and a `<param>`
			// that cannot is reported and left out (W3C SCXML 5.7.1).
			hostInvokeSrc := "helper.scxml"
			hostInvokeContent := ""
			hostInvokeParams := map[string][]string{}
			// The same pairs as the data model holds them, for the request's
			// EventData: one evaluation, read as text for Params and typed for
			// the JSON.
			hostInvokePayload := make([]sce.EventDataParam, 0)
			hostInvokeEventData := ""
			if len(hostInvokePayload) > 0 {
				hostInvokeEventData = sce.BuildJSONFromTypedParams(hostInvokePayload)
			}
			if !engine.PerformHostInvoke(sce.HostInvokeRequest{
				ProcessorType: "http://sce.dev/ext/test-component",
				InvokeID:      "helper",
				Src:           hostInvokeSrc,
				Params:        hostInvokeParams,
				EventData:     hostInvokeEventData,
				Content:       hostInvokeContent,
			}) {
				// W3C SCXML 6.4.1: declared but no invoker registered. The
				// document asked for a process to be run and none was, which
				// is the same fact as an unsupported type — so the same
				// event, rather than a silence that reads as started.
				engine.Raise(sce.NewPlatformError(JobTesterEventErrorExecution, sceerrorreason.ErrorReasonProcessorUnregistered, "<invoke> names an invoker the host declared but never registered"))
			}
			continue
		}
	}
}

