// InitialState returns the initial state (W3C SCXML 3.3).
func (p *JobTesterPolicy) InitialState() JobTesterState {
	return JobTesterStateRequesting
}

// IsFinalState returns true if state is a <final> state (W3C SCXML 3.7).
func (p *JobTesterPolicy) IsFinalState(state JobTesterState) bool {
	switch state {
	case JobTesterStateFailed:
		return true
	case JobTesterStatePassed:
		return true
	}
	return false
}

// GetParent returns the parent of state, or (zero, false) if root (W3C SCXML 3.3).
func (p *JobTesterPolicy) GetParent(state JobTesterState) (JobTesterState, bool) {
	switch state {
	case JobTesterStateRequesting:
		return JobTesterStateRunning, true
	case JobTesterStateSettling:
		return JobTesterStateRunning, true
	}
	return 0, false
}

// IsCompoundState returns true if state is a <state> with child states — exactly
// the states that have an initial transition. A <parallel> is not compound
// (W3C SCXML 3.3).
